</div>

<div class="title-page">
<h1>The Future is Unwritten</h1>
<h2>A Memoir by Robert Mills</h2>
</div>

<div class="dedication">
<h2>Dedication</h2>
<p>To my wife and all of our children, grandchildren, and great grandchildren, and to the leaders, coworkers and employees that have touched Bob's life.</p>
</div>

<div class="acknowledgments">
<h2>Acknowledgments</h2>
<p>I would like to thank my family for their unwavering support, my friends for their encouragement, and all those who shared their stories with me.</p>
</div>

<div class="toc">
<h2>Table of Contents</h2>
<ul>
<li>Part One: The Ignition .................. 1</li>
<li>Chapter 1: The Shock</li>
<li>Chapter 2: Mr. Chips</li>
<li>Chapter 3: The Echoes of Sputnik and a Family Legacy</li>
<li>Part Two: The Building ................. 89</li>
<li>Chapter 4: The Garage</li>
<li>Chapter 5: The Spark Ignites</li>
<li>Chapter 6: Life as an Engineer</li>
<li>Chapter 7: Foundations</li>
<li>Chapter 8: The Diagnosis</li>
<li>Chapter 9: The New Partnership</li>
<li>Chapter 10: The Y2K Challenge</li>
<li>Chapter 11: The New Beginning</li>
<li>Chapter 12: The Legacy</li>
<li>Epilogue ................................ 495</li>
</ul>
</div>
"""

# Extract chapter content from backup
for i, chapter in enumerate(chapters):
    # Find chapter in backup
    chap_start = backup_content.find(chapter)
    if chap_start == -1:
        print(f"Warning: Chapter '{chapter}' not found in backup")
        continue

    # Find next chapter or end
    next_chap_pos = len(backup_content)
    for next_chap in chapters:
        if next_chap != chapter:
            pos = backup_content.find(next_chap, chap_start + len(chapter))
            if pos != -1 and pos < next_chap_pos:
                next_chap_pos = pos

    # Extract chapter text
    chap_text = backup_content[chap_start:next_chap_pos]

    # Remove chapter header to get content
    header_end = chap_text.find('\n')
    if header_end != -1:
        content_only = chap_text[header_end+1:].strip()
    else:
        content_only = chap_text.strip()

    # Add page break
    html_content += '<div class="page-break"></div>\n'

    # Add chapter header
    html_content += f'<h3>{chapter}</h3>\n'

    # Add chapter image (proper placement right after header)
    html_content += f'<img src="chapter{i+1}.png" alt="{chapter}" class="chapter-image">\n'

    # Convert markdown to HTML
    if content_only:
        # Split into paragraphs
        paragraphs = content_only.split('\n\n')
        for para in paragraphs:
            para = para.strip()
            if para:
                # Handle headings (## and #)
                if para.startswith('##'):
                    html_content += f'<h4>{para[2:].strip()}</h4>\n'
                elif para.startswith('#'):
                    html_content += f'<h3>{para[1:].strip()}</h3>\n'
                else:
                    # Escape HTML special characters
                    para = para.replace('&', '&').replace('<', '<').replace('>', '>')
                    html_content += f'<p>{para}</p>\n'

# Add transitions between chapters
# Find all transition headers and map them to our chapters
transition_headers = re.findall(r'### Transition: From .* to .*', backup_content)

for i in range(len(chapters)-1):
    # Find the transition that should go between this chapter and the next
    from_chapter = chapters[i]
    to_chapter = chapters[i+1]

    # Search for a transition that mentions both chapters
    found_transition = None
    for trans in transition_headers:
        if from_chapter in trans and to_chapter in trans:
            found_transition = trans
            break

    if found_transition:
        trans_start = backup_content.find(found_transition)
        if trans_start != -1:
            # Extract transition content
            lines = backup_content[trans_start:].split('\n')
            trans_content = []
            in_trans = False

            for line in lines[1:]:  # Skip the header line
                if line.strip().startswith('['):
                    in_trans = True
                    continue
                if in_trans:
                    if line.strip().startswith('###') or line.strip().startswith('##') or line.strip().startswith('#'):
                        break
                    if line.strip():
                        trans_content.append(line)
                    else:
                        break

            if trans_content:
                # Create transition div
                html_content += '<div class="transition">\n'
                # Convert markdown to HTML
                trans_text = '\n'.join(trans_content)
                trans_paragraphs = trans_text.split('\n\n')
                for trans_para in trans_paragraphs:
                    trans_para = trans_para.strip()
                    if trans_para:
                        trans_para = trans_para.replace('&', '&').replace('<', '<').replace('>', '>')
                        html_content += f'<p>{trans_para}</p>\n'
                html_content += '</div>\n'

# Add epilogue
epilogue = """
Looking back across the years, I am filled with gratitude for the journey. The future may be unwritten, but the past has shaped us in ways we are only beginning to understand. To my family, my friends, and all who have touched my life—thank you.
"""

html_content += '<div class="page-break"></div>\n'
html_content += '<h3>Epilogue: The Unwritten Future</h3>\n'
html_content += f'<p>{epilogue}</p>\n'

# Add back cover
back_cover = """
<h2>About the Author</h2>
<p>Robert Mills is a retired engineer and executive who has lived a life full of adventure, challenges, and triumphs. He resides in Michigan with his wife, where they enjoy spending time with their children, grandchildren, and great grandchildren.</p>

<h2>Other Books by Robert Mills</h2>
<p>First Generation (Hard Sci-Fi)<br>
Second Generation (Sequel)<br>
The Future is Unwritten (Memoir)<br>
Small Business AI Book (Guide)</p>

<h2>Copyright</h2>
<p>© 2025 by Robert Mills. All rights reserved.</p>
"""

html_content += '<div class="page-break"></div>\n'
html_content += '<div class="back-cover">\n'
html_content += back_cover
html_content += '</div>\n'

